window.__TESTBOEGEN_EXTRA = [{"id":"2.2.11-001-M","th":"2.2","thd":"Verhalten Im Strassenverkehr","the":"Behaviour In Traffic","ch":"2.2.11","chd":"","che":"","pt":4,"qd":"Warum müssen Sie jetzt besonders aufmerksam sein?","qe":"Warum müssen Sie jetzt besonders aufmerksam sein?","od":["Weil sich der Verkehr in der Straße, in die ich einbiegen möchte, staut","Weil der Lkw beim Abbiegen sehr langsam werden wird","Weil die Ampel auf „Rot” umschalten könnte"],"oe":["Weil sich der Verkehr in der Straße, in die ich einbiegen möchte, staut","Weil der Lkw beim Abbiegen sehr langsam werden wird","Weil die Ampel auf „Rot” umschalten könnte"],"ans":[0,1,2],"t":"multi","num":null,"cd":"Alle drei Antworten sind richtig. Sie müssen jetzt besonders aufmerksam sein, weil der Lkw beim Abbiegen sehr langsam werden wird, sich der Verkehr in der Straße, in die ich einbiegen möchte, staut und die Ampel auf „Rot” umschalten könnte. Diese Frage ist eine Mutterfrage mit variablen Bildern und variablem Film. Bei dieser Frage kann in der Theorieprüfung die Bilder und der Film ausgetauscht werden. Die in der Prüfung zum Einsatz kommenden variablen Bilder und Filme wurden nicht veröffentlicht.","ce":"Alle drei Antworten sind richtig. Sie müssen jetzt besonders aufmerksam sein, weil der Lkw beim Abbiegen sehr langsam werden wird, sich der Verkehr in der Straße, in die ich einbiegen möchte, staut und die Ampel auf „Rot” umschalten könnte. Diese Frage ist eine Mutterfrage mit variablen Bildern und variablem Film. Bei dieser Frage kann in der Theorieprüfung die Bilder und der Film ausgetauscht werden. Die in der Prüfung zum Einsatz kommenden variablen Bilder und Filme wurden nicht veröffentlicht.","img":null,"vid":false,"u":""},{"id":"2.2.03-015","th":"2.2","thd":"Verhalten Im Strassenverkehr","the":"Behaviour In Traffic","ch":"2.2.03","chd":"Geschwindigkeit","che":"Speed","pt":4,"qd":"Wie lautet die Faustformel, um den Bremsweg einer Gefahrbremsung auf ebener, trockener und asphaltierter Fahrbahn auszurechnen?","qe":"What is the rule of thumb when calculating the braking distance for emergency braking on a dry, even and asphalted roadway?","od":["({Geschwindigkeit in km/h}/{10} x {Geschwindigkeit in km/h}/{10}) : 2","({Geschwindigkeit in km/h}/{10} x 5) : 2","({Geschwindigkeit in km/h}/{10} x 3) : 2"],"oe":["({Speed in km/h}/{10} x {Speed in km/h}/{10}) : 2","({Speed in km/h}/{10} x 5) : 2","({Speed in km/h}/{10} x 3) : 2"],"ans":[0],"t":"single","num":null,"cd":"({Geschwindigkeit in km/h}/{10} x {Geschwindigkeit in km/h}/{10}) : 2\n\nDas ist die korrekte Formel für die Berechnung des Bremswegs bei Gefahrenbremsung. Hierfür wird die Formel zur Berechnung des Bremswegs verwendet, nur das bei der Berechnung bei Gefahrenbremsung das Ergebnis durch 2 geteilt wird.","ce":"The rule of thumb for the braking distance during emergency braking is: speed divided by 10, squared, divided by 2.","img":null,"vid":false,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.2.-behaviour-in-traffic/2.2.03-speed/2.2.03-015"},{"id":"2.7.01-047","th":"2.7","thd":"Technik","the":"Technology","ch":"2.7.01","chd":"Fahrbetrieb Fahrphysik Fahrtechnik","che":"Driving Operation Driving Physics Driving Technique","pt":3,"qd":"Wodurch wird die auf ein Fahrzeug wirkende Fliehkraft bei Kurvenfahrt vergrößert?","qe":"What increases the effect of centrifugal force on the vehicle when driving round bends?","od":["Durch höhere Geschwindigkeit","Durch kleineren Kurvenradius","Durch höheren Reifenluftdruck"],"oe":["Higher speed","Smaller radius of a bend","Higher tyre pressure"],"ans":[0,1],"t":"multi","num":null,"cd":"Die Geschwindigkeit wirkt sich unmittelbar auf die Höhe der Fliehkraft aus. Ihr Bremsweg vervierfacht sich, wenn Sie mit doppelter Geschwindigkeit fahren. Die Fliehkraft wird größer, je kleiner der Kurvenradius ist. Keinerlei Auswirkung auf die Fliehkraft hat der Reifendruck.","ce":"The speed has an immediate effect on the level of centrifugal force. Your braking distance quadruples when you drive at twice the speed. The centrifugal force increases the smaller the curve radius. The tire pressure has no effect on the centrifugal force.","img":null,"vid":false,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.7.-technology/2.7.01-driving-operation-driving-physics-driving-technique/2.7.01-047"},{"id":"2.5.01-014","th":"2.5","thd":"Umweltschutz","the":"Environmental Protection","ch":"2.5.01","chd":"Umweltschutz","che":"Environmental Protection","pt":3,"qd":"Was erhöht den Kraftstoffverbrauch Ihres Fahrzeugs deutlich?","qe":"What increases the fuel consumption of your vehicle considerably?","od":["- der Sitzheizung","- der Klimaanlage","- des Navigationsgerätes"],"oe":["- heated seats","- the air-conditioning","- the navigation device"],"ans":[0,1],"t":"multi","num":null,"cd":"Wenn Sie die Sitzheizung oder die Klimaanlage Ihres Fahrzeugs einschalten, wird viel Energie verbraucht und der Kraftstoffverbrauch Ihres Kfz erhöht sich deutlich. Im Vergleich zu diesen Geräten benötigen Navigationsgeräte relativ wenig Strom.","ce":"Turning on the seat heating or air conditioning of your vehicle consumes a lot of energy and increases the fuel consumption of your car significantly. Navigation devices require relatively little power compared to these devices.","img":null,"vid":false,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.5.-environmental-protection/2.5.01-environmental-protection/2.5.01-014"},{"id":"2.2.18-019","th":"2.2","thd":"Verhalten Im Strassenverkehr","the":"Behaviour In Traffic","ch":"2.2.18","chd":"Autobahnen Und Kraftfahrstrassen","che":"Motorways And Motorways","pt":4,"qd":"Wie müssen Sie sich in einem Stau auf Autobahnen und auf Kraftfahrstraßen mit zwei Fahrstreifen für eine Richtung verhalten?","qe":"What must you do if you find yourself in a traffic jam on motorways and on highways with two lanes travelling in the same direction?","od":["- rechten Fahrstreifen möglichst weit rechts fahren","- linken Fahrstreifen möglichst weit links fahren","- rechten Fahrstreifen möglichst weit links fahren"],"oe":["- drive as far to the right as possible in the right-hand lane","- drive as far to the left as possible in the left-hand lane","- drive as far to the left as possible in the right-hand lane"],"ans":[0,1],"t":"multi","num":null,"cd":"Entweder auf dem linken Fahrstreifen möglichst weit links fahren oder auf dem rechten möglichst weit rechts um eine Rettungsgasse bilden zu können.","ce":"If vehicles stand or drive at walking speed on freeways or on roads outside of built-up areas with at least two lanes for one direction, the following applies: You, as a car driver, must participate in forming a free lane between the leftmost and rightmost lane for the passage of police and support vehicles.","img":null,"vid":false,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.2.-behaviour-in-traffic/2.2.18-motorways-and-motorways/2.2.18-019"},{"id":"2.1.03-036","th":"2.1","thd":"Gefahrenlehre","the":"Danger Teaching","ch":"2.1.03","chd":"Fahrbahn Und Witterungsverhaeltnisse","che":"Road And Weather Conditions","pt":3,"qd":"Wie verhalten Sie sich in dieser Situation richtig?","qe":"What is the correct course of action in this situation?","od":["Ich verringere die Geschwindigkeit","Ich vermeide ruckartiges Lenken","Ich bremse stark ab"],"oe":["I reduce my speed","I avoid abrupt steering movements","I brake hard"],"ans":[0,1],"t":"multi","num":null,"cd":"Das Verkehrsschild zeigt Schleuder- und Rutschgefahr an. Um nicht ins Schleudern zu geraten, solltest du deine Geschwindigkeit reduzieren, vor allem dann, wenn es, wie hier, regnet und Laub auf die Straße fällt. Durch starkes Bremsen, starkes Beschleunigen oder ruckartiges Lenken können die Reifen ihre Haftung verlieren und du könntest ins Rutschen oder Schleudern geraten.","ce":"The traffic sign indicates a risk of skidding and sliding. To avoid skidding, you should reduce your speed, especially when it is raining and leaves are falling on the road, as is the case here. Braking hard, accelerating hard or steering jerkily can cause the tyres to lose their grip and you could skid or slide.","img":"2_1_03-036","vid":false,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.1.-danger-teaching/2.1.03-road-and-weather-conditions/2.1.03-036"},{"id":"2.1.06-014","th":"2.1","thd":"Gefahrenlehre","the":"Danger Teaching","ch":"2.1.06","chd":"Ueberholen","che":"Overtaking","pt":5,"qd":"Wie verhalten Sie sich richtig?","qe":"What is the right course of action?","od":["Ich setze den Überholvorgang zügig fort","Ich breche den Überholvorgang ab und schere wieder nach rechts ein","Ich bremse, setze den Überholvorgang aber fort"],"oe":["I quickly continue the overtaking manoeuvre","I cease the overtaking manoeuvre, and pull back into the right-hand lane","I brake, but continue the overtaking manoeuvre"],"ans":[0],"t":"single","num":null,"cd":"Bei sich schnell annährenden Fahrzeugen von hinten gilt es sich nicht aus der Ruhe bringen zu lassen, den Überholvorgang abzuschließen und bei der nächsten Möglichgkeit den Fahrstreifen frei zu machen.","ce":"While overtaking a truck, you observe a fast approaching car in the rearview mirror. It is too late to complete the overtaking process. Accelerate and complete the overtaking process quickly but safely. Basically, subsequent vehicles do not have priority; even not on the freeway.","img":"2_1_06-014","vid":true,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.1.-danger-teaching/2.1.06-overtaking/2.1.06-014"},{"id":"2.1.08-013","th":"2.1","thd":"Gefahrenlehre","the":"Danger Teaching","ch":"2.1.08","chd":"Autobahn","che":"Motorway","pt":5,"qd":"Was müssen Sie beim Einfahren auf die Autobahn beachten?","qe":"What must you be aware of when joining the motorway?","od":["Auf dem Einfädelungsstreifen darf ich schneller fahren als auf der durchgehenden Fahrbahn","Der Verkehr auf der durchgehenden Fahrbahn hat Vorfahrt","Der Verkehr auf dem durchgehenden rechten Fahrstreifen muss das Einfahren ermöglichen"],"oe":["On the merging lane, I may drive faster than the through-driving traffic","The through-driving traffic has priority","The through-driving traffic on the right-hand lane must allow incoming traffic to merge"],"ans":[0,1],"t":"multi","num":null,"cd":"Auf Autobahnen hat immer der durchgehende Verkehr Vorfahrt und muss die Einfahrt nicht ermöglichen. Auf dem Einfädelungsstreifen darf der/die Kfz-FahrerIn schneller fahren als die restlichen Fahrzeuge.","ce":"On the freeway, the continuous traffic always has the right of way and does not have to allow entrance. On the acceleration lane the driver may drive faster than the rest of the vehicles.","img":null,"vid":false,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.1.-danger-teaching/2.1.08-motorway/2.1.08-013"},{"id":"2.1.06-013","th":"2.1","thd":"Gefahrenlehre","the":"Danger Teaching","ch":"2.1.06","chd":"Ueberholen","che":"Overtaking","pt":5,"qd":"Sie möchten überholen. Wie verhalten Sie sich jetzt richtig?","qe":"You want to overtake. What is the right course of action now?","od":["Ich breche den Überholvorgang ab und bleibe hinter dem Lkw","Ich beschleunige und setze den Überholvorgang zügig fort","Ich behalte die Geschwindigkeit bei und setze den Überholvorgang fort"],"oe":["I cease the overtaking manoeuvre and remain behind the truck","I accelerate and quickly continue the overtaking manoeuvre","I maintain my speed and continue the overtaking manoeuvre"],"ans":[0],"t":"single","num":null,"cd":"Sie haben den Blinker bereits gesetzt und möchten den Lkw überholen. Im Rückspiegel sehen Sie, wie sich ein roter Pkw mit hoher Geschwindigkeit auf dem linken Fahrstreifen nähert. Sie müssen den Überholvorgang sofort abbrechen und hinter dem Lkw bleiben. Setzen Sie ihn fort, zwingen Sie den roten Pkw zum starken Abbremsen. Er könnte auf Ihr Fahrzeug auffahren.","ce":"You already indicated and want to overtake the truck. In the rearview mirror you can see a red car approaching on the left lane at high speed. You need to stop the overtaking process immediately and stay behind the truck. If you continue, you force the red car to brake suddenly. He could drive against your car.","img":"2_1_06-013","vid":true,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.1.-danger-teaching/2.1.06-overtaking/2.1.06-013"},{"id":"2.6.01-003","th":"2.6","thd":"Vorschriften Ueber Den Betrieb Der Fahrzeuge","the":"Rules On The Operation Of The Vehicles","ch":"2.6.01","chd":"Untersuchung Der Fahrzeuge","che":"Examination Of The Vehicles","pt":2,"qd":"Woran können Sie erkennen, wann Sie Ihr Fahrzeug zur nächsten Hauptuntersuchung vorführen müssen?","qe":"How can you tell when you need to bring your vehicle in for its next vehicle roadworthiness test?","od":["An der Prüfplakette auf dem hinteren amtlichen Kennzeichen","An der Eintragung in der Zulassungsbescheinigung Teil I","An der Eintragung in der Bedienungsanleitung meines Fahrzeugs"],"oe":["By looking at the inspection tag on the rear license plate","By reading the entry made in the registration certificate Part I","By reading the entry in the operating manual for my vehicle"],"ans":[0,1],"t":"multi","num":null,"cd":"Zum einen kannst du es an der Eintragung in der Zulassungsbescheinigung Teil I erkennen und an der Prüfplakette auf dem hinteren amtlichen Kennzeichen. Die Bedienungsanleitung ist keine Hilfe dafür.","ce":"The date for the next main inspection of your vehicle can be found in the certificate of registration part 1. In addition, the appointment is clearly visible on the inspection plate printed on your license plate.","img":null,"vid":false,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.6.-rules-on-the-operation-of-the-vehicles/2.6.01-examination-of-the-vehicles/2.6.01-003"},{"id":"2.7.01-058","th":"2.7","thd":"Technik","the":"Technology","ch":"2.7.01","chd":"Fahrbetrieb Fahrphysik Fahrtechnik","che":"Driving Operation Driving Physics Driving Technique","pt":4,"qd":"Sie fahren bei Nässe mit einem Pkw und Anhänger auf einer schmalen Landstraße und nähern sich einer übersichtlichen, aber engen Linkskurve. Wie verhalten Sie sich?","qe":"You are driving in the wet in a car with trailer on a narrow rural road and are approaching a clearly visible but tight left-hand bend. What should you do?","od":["Ich verringere die Geschwindigkeit vor der Kurve","Ich bleibe in der Mitte des Fahrstreifens und beschleunige erst wieder beim Übergang in die Gerade","Ich bremse erst im Scheitelpunkt der Kurve"],"oe":["I reduce my speed before the bend","I remain in the centre of the lane and only accelerate again once I am back on the straight","I only brake once I have reached the apex of the bend"],"ans":[0,1],"t":"multi","num":null,"cd":"Verringern Sie vor der Kurve Ihre Geschwindigkeit. Berücksichtigen Sie dabei die Witterungsverhältnisse. Bedenken Sie, dass die Fliehkraft doppelt so schnell wächst wie die Geschwindigkeit. Erst im Kurven-Scheitelpunkt sollten Sie wieder beschleunigen.","ce":"Decrease your speed before the turn. Take the weather conditions into account. Keep in mind that the centrifugal force grows twice as fast as the speed. You should only accelerate again in the curve vertex.","img":null,"vid":false,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.7.-technology/2.7.01-driving-operation-driving-physics-driving-technique/2.7.01-058"},{"id":"2.1.11-012","th":"2.1","thd":"Gefahrenlehre","the":"Danger Teaching","ch":"2.1.11","chd":"Affektiv Emotionales Verhalten Im Strassenverkehr","che":"Affective Emotional Behaviour In Road Traffic","pt":3,"qd":"Was müssen Sie beachten, wenn Sie nach einem langen Arbeitstag noch ein Fahrzeug führen?","qe":"What should you be aware of when driving a car after a long day's work?","od":["Ich fahre weniger konzentriert","Ich werde schneller müde","Ich mache weniger Fahrfehler"],"oe":["I drive with a lower level of concentration","I will become tired more quickly","I make fewer driving errors"],"ans":[0,1],"t":"multi","num":null,"cd":"Nach einem langen Arbeitstag sind Sie meist nicht mehr voll leistungsfähig und werden schneller müde. Deswegen können auch Ihre Fahrfehler zunehmen und Ihre Konzentration nachlassen.","ce":"After a long day at work, you are usually not fully productive and get tired faster. That's why mistakes while driving can increase and your concentration decreases.","img":null,"vid":false,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.1.-danger-teaching/2.1.11-affective-emotional-behaviour-in-road-traffic/2.1.11-012"},{"id":"2.2.03-006","th":"2.2","thd":"Verhalten Im Strassenverkehr","the":"Behaviour In Traffic","ch":"2.2.03","chd":"Geschwindigkeit","che":"Speed","pt":3,"qd":"Sie fahren 100 km/h, haben 1 Sekunde Reaktionszeit und führen eine normale Bremsung durch. Wie lang ist der Anhalteweg nach der Faustformel?","qe":"You are travelling at 100 km/h, have a reaction time of 1 second, and brake normally. What is the stopping distance according to the rule of thumb?","od":[],"oe":[],"ans":[],"t":"num","num":"130","cd":"Der Anhalteweg bei normaler Bremsung setzt sich zusammen aus der Addition von Reaktionsweg ((Geschwindigkeit : 10) x 3) und Bremsweg (Geschwindigkeit : 10) x (Geschwindigkeit : 10).\nAnhalteweg = Reaktionsweg + Bremsweg.\nDas heißt bei einer Geschwindigkeit von 100 km/h beträgt der Anhalteweg 130 Meter.","ce":"The stopping distance during normal braking consists of the addition of reaction distance ((speed: 10) x 3) and braking distance (speed: 10) x (speed: 10). Stopping distance = reaction path + braking distance. At a speed of 100 km/h, the stopping distance is 130 meters. \"","img":null,"vid":false,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.2.-behaviour-in-traffic/2.2.03-speed/2.2.03-006"},{"id":"2.1.08-026-M","th":"2.1","thd":"Gefahrenlehre","the":"Danger Teaching","ch":"2.1.08","chd":"Autobahn","che":"Motorway","pt":3,"qd":"Worauf sollten Sie sich jetzt einstellen?","qe":"What should you be prepared for now?","od":["[Der gelbe Pkw] verlässt die Autobahn","Das Motorrad verlässt die Autobahn","Der [blaue Bus] vor mir bremst wegen eines Staus"],"oe":["[The yellow car] exits the motorway","The motorbike exits the motorway","The [blue bus] in front of me brakes due to a traffic jam"],"ans":[0],"t":"single","num":null,"cd":"In dieser Situation lässt sich kein Stau ausmachen. Da das Motorrad links fährt, wird es nicht von der Autobahn abfahren. Der Pkw hingegen, der links von Ihnen fährt, blinkt nach rechts. Sie können sich darauf einstellen, dass der/die Kfz-FahrerIn die Autobahn verlässt.","ce":"No traffic jam can be seen in this situation. Since the motorcycle is driving on the left, it will not leave the motorway. On the other hand, the car driving on your left flashes to the right. You can be prepared for the driver to leave the motorway.","img":"2_1_08-026-M","vid":true,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.1.-danger-teaching/2.1.08-motorway/2.1.08-026-M"},{"id":"2.2.05-020-M","th":"2.2","thd":"Verhalten Im Strassenverkehr","the":"Behaviour In Traffic","ch":"2.2.05","chd":"Ueberholen","che":"Overtaking","pt":3,"qd":"Sie möchten das vor Ihnen fahrende Fahrzeug überholen. Was ist hierfür erforderlich?","qe":"You want to overtake the vehicle driving up ahead of you. What is necessary to allow you to do so?","od":["- meine Geschwindigkeit wesentlich erhöhen","- meine Überholabsicht durch Blinken anzeigen","- den rückwärtigen und seitlichen Verkehr beobachten"],"oe":["- considerably increase my speed","- use my indicator to signal my intention to overtake","- observe the traffic to the rear and side of me"],"ans":[0,1,2],"t":"multi","num":null,"cd":"Zeige anderen Verkehrsteilnehmern rechtzeitig an, dass du auf die linke oder mittlere Spur ziehen wirst. Jedes Überholen muss durch Blinken angezeigt werden. Nachdem du den rückwärtigen und seitlichen Verkehr beobachtet hast und sicherstellen konntest, dass die linke Spur frei ist, ist der Blinker zu betätigen. Anschließend kannst du die Spur wechseln und mit deutlich erhöhter Geschwindigkeit das langsamere Fahrzeug überholen.\nAchte nur darauf, dass du die zulässige Höchstgeschwindigkeit nicht überschreitest.","ce":"Show other road users in good time that you will move onto the left or medium lane. Each overtaking must be displayed by flashing. After you have observed the rear and side traffic and could make sure that the left lane is free, the indicator must be pressed. Then you can change the lane and overtake the slower vehicle at a much increased speed.\nJust make sure that you do not exceed the permissible maximum speed.","img":"2_2_05-020-M","vid":true,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.2.-behaviour-in-traffic/2.2.05-overtaking/2.2.05-020-M"},{"id":"2.2.12-204","th":"2.2","thd":"Verhalten Im Strassenverkehr","the":"Behaviour In Traffic","ch":"2.2.12","chd":"Halten Und Parken","che":"Stopping And Parking","pt":2,"qd":"Sie möchten am rechten Fahrbahnrand parken. Wie groß muss der Abstand zwischen Ihrem Fahrzeug und der durchgehenden Fahrstreifenbegrenzungslinie mindestens sein?","qe":"You want to park on the right-hand side edge of the carriageway. How big is the mandatory minimum distance between your vehicle and the solid lane boundary line?","od":[],"oe":[],"ans":[],"t":"num","num":"3","cd":"Wird beim Parken ein Mindestabstand von 3 Metern zur Fahrstreifenbegrenzungslinie eingehalten, so stellt das geparkte Auto kein Hindernis da.","ce":"If a minimum distance of 3 meters to the lane boundary line is observed when parking, the parked car will not present an obstacle.","img":null,"vid":false,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.2.-behaviour-in-traffic/2.2.12-stopping-and-parking/2.2.12-204"},{"id":"2.2.05-012","th":"2.2","thd":"Verhalten Im Strassenverkehr","the":"Behaviour In Traffic","ch":"2.2.05","chd":"Ueberholen","che":"Overtaking","pt":5,"qd":"Worauf müssen Sie sich jetzt einstellen?","qe":"What must you be prepared for now?","od":["- blaue Pkw zum Überholen ansetzt","- Überholvorgang des grünen Lkws länger dauert","- weiße Lkw beschleunigt"],"oe":["- blue car begins overtaking","- overtaking manoeuvre of the green truck takes longer to complete","- white truck accelerates"],"ans":[0,1],"t":"multi","num":null,"cd":"Sie müssen sich ggf. darauf einstellen, dass Sie jetzt nicht überholen können, weil die unmittelbaren anderen Verkehrsteilnehmer schon in Überholmanöver involviert sind. Handeln Sie nicht überstürzt, nur um den Überholvorgang in einer dafür zulässigen Strecke abzuschließen. Eine durchgezogene Linie bedeutet Überholverbot und ist gleichwertig mit dem Verkehrsschild \"Überholen verboten\".","ce":"You may have to be prepared for the fact that you cannot overtake now because the other road users are already involved in overtaking maneuvers. Do not act with precipitation just to complete the overtaking maneuver on the permissible route. A solid line represents a restriction on overtaking and is equivalent to the road sign \"No overtaking\".","img":"2_2_05-012","vid":true,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.2.-behaviour-in-traffic/2.2.05-overtaking/2.2.05-012"},{"id":"2.2.34-003-M","th":"2.2","thd":"Verhalten Im Strassenverkehr","the":"Behaviour In Traffic","ch":"2.2.34","chd":"Unfall","che":"Accident","pt":4,"qd":"Wie verhalten Sie sich jetzt richtig?","qe":"What is the right course of action now?","od":["Ich verringere meine Geschwindigkeit weiter","Ich fahre so weit wie möglich links","Ich fahre unverändert weiter"],"oe":["I reduce my speed further","I drive as far to the left as possible","I continue driving just as before"],"ans":[0,1],"t":"multi","num":null,"cd":"Im Falle eines Unfalls sollten Sie immer auf Nummer sicher gehen und den Sicherheitsabstand vergrößern wie auch Ihre Geschwindigkeit herabsetzen für den Fall dass jemand auf die Fahrbahn läuft.","ce":"In the event of an accident, you should always play it safe and increase the safe distance as well as reduce your speed in case someone runs into the lane.","img":"2_2_34-003-M","vid":true,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.2.-behaviour-in-traffic/2.2.34-accident/2.2.34-003-M"},{"id":"2.8.01-009","th":"2.8","thd":"Eignung Und Befaehigung Von Kraftfahrern","the":"Qualification And Ability Of Truck Drivers","ch":"2.8.01","chd":"Eignung Und Befaehigung Von Kraftfahrern","che":"Qualification And Ability Of Truck Drivers","pt":2,"qd":"Sie befinden sich in der Probezeit und sind bisher nicht auffällig geworden. Welche Folgen können eintreten, wenn Sie an dem Verkehrszeichen „Halt. Vorfahrt gewähren.“ nicht anhalten und dadurch andere Verkehrsteilnehmer gefährden?","qe":"You are currently in the probationary period and to date have not come to the attention of the authorities. What consequences may result if you fail to observe the traffic sign \"Stop. Give way.\" and thereby endanger other road users?","od":["Anordnung zur Teilnahme an einem Aufbauseminar für Fahranfänger","Eintrag in das Fahreignungsregister","Anordnung zum erneuten Ablegen einer theoretischen Fahrerlaubnisprüfung"],"oe":["An order to attend an advanced seminar for new drivers","Entry into the Central Register of Road Traffic Offenders","An order to resit a theoretical driving licence test"],"ans":[0,1],"t":"multi","num":null,"cd":"Das Nichtbeachten des Verkehrszeichens „Halt. Vorfahrt gewähren“ ist ein schwerwiegender Verstoß, ein A-Verstoß, der in das Fahreignungsregister eingetragen wird. Bei einem A-Verstoß oder zwei weniger schwerwiegenden Verstößen (B-Verstößen) innerhalb der Probezeit müssen Sie als FahranfängerIn an einem Aufbauseminar teilnehmen. Die Prüfung müssen Sie deswegen nicht erneut ablegen.","ce":"Failure to observe the traffic sign \"Stop. Grant right of way\" is a serious violation, an A violation, which is recorded in the driving qualifying register. In the event of an A-violation or two minor violations (B-violations) within the probationary period, you will have to attend a retraining seminar as a novice driver. You will not have to take an exam again.","img":null,"vid":false,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.8.-qualification-and-ability-of-truck-drivers/2.8.01-qualification-and-ability-of-truck-drivers/2.8.01-009"},{"id":"2.1.07-208","th":"2.1","thd":"Gefahrenlehre","the":"Danger Teaching","ch":"2.1.07","chd":"Besondere Verkehrssituationen","che":"Special Traffic Situations","pt":3,"qd":"Sie erhöhen Ihre Geschwindigkeit von 50 km/h auf 100 km/h. Wie verändert sich der Reaktionsweg entsprechend der Faustformel?","qe":"You increase your speed from 50 km/h to 100 km/h. How does the reaction distance change in accordance with the rule of thumb?","od":["Er verdoppelt sich von 15 m auf 30 m","Er vervierfacht sich von 25 m auf 100 m","Er halbiert sich von 50 m auf 25 m"],"oe":["It is doubled from 15 m to 30 m","It is quadrupled from 25 m to 100 m","It is halved from 50 m to 25 m"],"ans":[0],"t":"single","num":null,"cd":"Erhöht der/die Kfz-FahrerIn die Geschwindigkeit des Fahrzeugs auf das Doppelte, so verdoppelt sich der Reaktionsweg von bisher 15 auf 30 Meter.","ce":"If the car driver doubles the speed of the vehicle, the braking distance doubles from 15 to 30 meters.","img":null,"vid":false,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.1.-danger-teaching/2.1.07-special-traffic-situations/2.1.07-208"},{"id":"2.1.03-044-M","th":"2.1","thd":"Gefahrenlehre","the":"Danger Teaching","ch":"2.1.03","chd":"Fahrbahn Und Witterungsverhaeltnisse","che":"Road And Weather Conditions","pt":4,"qd":"Womit müssen Sie in dieser Situation rechnen?","qe":"What must you anticipate in this situation?","od":["Mein Kraftfahrzeug kann nach links versetzt werden","Beim Einfahren in den Windschatten des Lkws kann mein Kraftfahrzeug nach rechts versetzt werden","Der vorausfahrende Lkw kann nach rechts versetzt werden"],"oe":["My vehicle may be forced leftwards","When driving into the wind-protected area alongside the truck, my vehicle may be forced rightwards","The truck ahead of me may be forced rightwards"],"ans":[0,1],"t":"multi","num":null,"cd":"An der Windhose kannst du sehen, dass von rechts starker Wind weht. Durch den starken Wind könnte dein Kraftfahrzeug nach links versetzt werden. Sei bereit, nach rechts gegenzulenken.\nAußerdem musst du, beim Einfahren in den Windschatten des Lkws, damit rechnen das dein Kraftfahrzeug nach rechts versetzt werden könnte, weil seine große Fläche den Seitenwind abhält. Sei bereit, nach links gegenzulenken, um nicht mit dem Lkw zu kollidieren.","ce":"You can see from the windsock that a strong wind is blowing from the right. The strong wind could move your vehicle to the left. Be prepared to steer to the right.\nIn addition, when entering the slipstream of the truck, you must be prepared for your vehicle to be moved to the right because its large surface area will keep out the crosswind. Be prepared to steer to the left to avoid colliding with the truck.","img":"2_1_03-044-M","vid":false,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.1.-danger-teaching/2.1.03-road-and-weather-conditions/2.1.03-044-M"},{"id":"2.2.18-013","th":"2.2","thd":"Verhalten Im Strassenverkehr","the":"Behaviour In Traffic","ch":"2.2.18","chd":"Autobahnen Und Kraftfahrstrassen","che":"Motorways And Motorways","pt":4,"qd":"Wie müssen Sie sich jetzt verhalten?","qe":"What must you do now?","od":["- weit nach rechts","- weit nach links","- in der Mitte"],"oe":["- as far to the right as possible","- as far to the left as possible","- in the centre"],"ans":[0],"t":"single","num":null,"cd":"Sie nähern sich auf der Autobahn dem Ende eines Staus. Schalten Sie das Warnblinklicht ein. Bilden Sie eine Gasse in der Mitte der Richtungsfahrbahn zur Durchfahrt von Polizei- und Hilfsfahrzeugen: bei Fahrbahnen mit drei Fahrstreifen für eine Richtung zwischen dem linken und dem mittleren Fahrstreifen. Daher müssen Sie weit nach rechts fahren. Die Regel gilt außerhalb geschlossener Ortschaften und auf Autobahnen.","ce":"You approach the end of a traffic jam on the freeway. Turn on the hazard light. Form an alley in the middle of the lane for the passage of police and helping vehicles: on roads with three lanes for one direction, form an alley between the left and middle lane. Therefore, you have to drive far to the right. This rule applies outside built-up areas and on freeways.","img":"2_2_18-013","vid":true,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.2.-behaviour-in-traffic/2.2.18-motorways-and-motorways/2.2.18-013"},{"id":"2.1.06-007-M","th":"2.1","thd":"Gefahrenlehre","the":"Danger Teaching","ch":"2.1.06","chd":"Ueberholen","che":"Overtaking","pt":3,"qd":"Sie möchten überholen. Wie verhalten Sie sich jetzt richtig?","qe":"You want to overtake. What is the right course of action now?","od":["Ich verzichte auf das Überholen","Ich beschleunige","Ich behalte die Geschwindigkeit bei"],"oe":["I refrain from overtaking","I accelerate","I maintain my speed"],"ans":[0],"t":"single","num":null,"cd":"Da das Fahrzeug hinter dir den Überholvorgang bereits gestartet hat, solltest du auf das Überholen verzichten.","ce":"As the vehicle behind you has already started the overtaking process, you should refrain from overtaking.","img":"2_1_06-007-M","vid":true,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.1.-danger-teaching/2.1.06-overtaking/2.1.06-007-M"},{"id":"2.1.08-032-M","th":"2.1","thd":"Gefahrenlehre","the":"Danger Teaching","ch":"2.1.08","chd":"Autobahn","che":"Motorway","pt":4,"qd":"Womit müssen Sie jetzt rechnen?","qe":"What must you anticipate here?","od":["Der Fahrer des [gelben Lkws] sieht das Stauende zu spät","Das Motorrad fährt zwischen den Fahrzeugreihen durch","[Der blaue Pkw] schert vor mir ein"],"oe":["The driver of the [yellow truck] does not notice the start of the tailback in time","The motorbike drives between the lines of vehicles","[The blue car] pulls into my lane in front of me"],"ans":[0,1],"t":"multi","num":null,"cd":"Aufgrund des plötzlichen Staus sieht der Fahrer des Lkw das Stauende zu spät. Das Motorrad wird aufgrund des Staus versuchen, zwischen den Fahrzeugreihen durchzufahren.","ce":"Due to the sudden traffic jam, the driver of the truck sees the end of the traffic jam too late. Due to the traffic jam, the motorcycle will try to go through the rows of vehicles.","img":"2_1_08-032-M","vid":true,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.1.-danger-teaching/2.1.08-motorway/2.1.08-032-M"},{"id":"2.2.12-003","th":"2.2","thd":"Verhalten Im Strassenverkehr","the":"Behaviour In Traffic","ch":"2.2.12","chd":"Halten Und Parken","che":"Stopping And Parking","pt":3,"qd":"Wo ist das Parken verboten?","qe":"Where is parking prohibited?","od":["Auf schmalen Fahrbahnen gegenüber Ein- und Ausfahrten von Grundstücken","An Taxenständen","Unmittelbar hinter Fußgängerüberwegen"],"oe":["On narrow roadways opposite driveway entrances and exits","At taxi ranks","Immediately behind pedestrian crossings"],"ans":[0,1],"t":"multi","num":null,"cd":"Ein Parkverbot gemäß der StVO gilt an allen Stellen, an denen andere VerkehrsteilnehmerInnen behindert werden können oder die öffentliche Ordnung und Sicherheit durch parkende Autos nicht mehr gewährleistet ist. So gilt Parkverbot z. B. an Taxiständen, schmalen Fahrbahnen oder Ein- und Ausfahrten gegenüber von Grundstücken sowie auf und bis 5 m vor Fußgängerüberwegen.","ce":"A parking ban in accordance with the road traffic act applies in all places where other road users can be obstructed or the public order and safety is no longer guaranteed by parked cars. For example, parking is prohibited at taxi stands, narrow lanes or entrances and exits in front of property as well as on and up to 5 m before pedestrian crossings.","img":null,"vid":false,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.2.-behaviour-in-traffic/2.2.12-stopping-and-parking/2.2.12-003"},{"id":"2.4.41-005-M","th":"2.4","thd":"Verkehrszeichen","the":"Traffic Sign","ch":"2.4.41","chd":"Vorschriftzeichen","che":"Regulatory Sign","pt":3,"qd":"Wie verhalten Sie sich jetzt richtig?","qe":"What is the right behaviour now?","od":["Ich beschleunige","Ich behalte meine Geschwindigkeit bei","Ich beschleunige erst, wenn die Geschwindigkeitsbegrenzung durch ein Verkehrszeichen aufgehoben wird"],"oe":["I accelerate","I maintain my speed","I only accelerate when the speed limit is removed by a road sign"],"ans":[0],"t":"single","num":null,"cd":"Du darfst beschleunigen, da du die Baustelle mit der Geschwindigkeitsbeschränkung passiert hast, zurück auf die richtige Fahrspur gewechselt bist und die Straße vor dir frei ist.","ce":"You are allowed to accelerate because you have passed the construction site with the speed limit, moved back into the correct lane and the road in front of you is clear.","img":"2_4_41-005-M","vid":true,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.4.-traffic-sign/2.4.41-regulatory-sign/2.4.41-005-M"},{"id":"2.2.37-002","th":"2.2","thd":"Verhalten Im Strassenverkehr","the":"Behaviour In Traffic","ch":"2.2.37","chd":"Wechsellichtzeichen Und Dauerlichtzeichen","che":"Variable And Steady Light Signals","pt":4,"qd":"Sie fahren mit ungefähr 40 km/h. Etwa 10 m vor Ihnen wechselt die Ampel von „Grün“ auf „Gelb“. Wie verhalten Sie sich?","qe":"You are travelling at a speed of approximately 40 km/h. The lights change from \"green\" to \"amber\" when you are 10 m away. What do you do?","od":["Weiterfahren","Anhalten"],"oe":["Proceed","Stop"],"ans":[0],"t":"single","num":null,"cd":"Bei gefahrenen 40 km/h beträgt der Bremsweg nach der Faustformel 28 Meter. Selbst mit einer Gefahrenbremsung kann ein/eine Kfz-FahrerIn 10 Meter vor einer Ampel kaum noch rechtzeitig zum Stehen kommen. Um einen möglichen Auffahrunfall zu verhindern, sollten Sie deshalb weiterfahren.","ce":"At 40 km/h, the braking distance according to the rule of thumb is 28 meters. Even with emergency braking, a car driver can barely come to a halt 10 meters in front of a traffic light. To prevent a possible rear-end collision, you should therefore continue driving.","img":null,"vid":false,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.2.-behaviour-in-traffic/2.2.37-variable-and-steady-light-signals/2.2.37-002"},{"id":"2.1.08-027-M","th":"2.1","thd":"Gefahrenlehre","the":"Danger Teaching","ch":"2.1.08","chd":"Autobahn","che":"Motorway","pt":4,"qd":"Sie möchten die Autobahn verlassen. Wodurch ergibt sich hier eine gefährliche Situation?","qe":"You want to exit the motorway. What is creating a dangerous situation here?","od":["Durch das Motorrad","Durch [den gelben Lkw]","Durch [das grüne Fahrzeug]"],"oe":["The motorbike","[The yellow truck]","[The green vehicle]"],"ans":[0],"t":"single","num":null,"cd":"Durch das hinter dir fahrende Motorrad (siehe rechter Außenspiegel) ergibt sich für dich eine gefährliche Situation. Berücksichtige dies beim Verlassen der Autobahn.","ce":"The motorbike behind you (see right wing mirror) creates a dangerous situation for you. Take this into account when leaving the motorway.","img":"2_1_08-027-M","vid":true,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.1.-danger-teaching/2.1.08-motorway/2.1.08-027-M"},{"id":"2.2.18-017-M","th":"2.2","thd":"Verhalten Im Strassenverkehr","the":"Behaviour In Traffic","ch":"2.2.18","chd":"Autobahnen Und Kraftfahrstrassen","che":"Motorways And Motorways","pt":3,"qd":"Wie sollten Sie sich jetzt verhalten?","qe":"What should you do now?","od":["Ich beschleunige und fädele vor dem [Lkw] ein","Ich verzögere und fädele zwischen dem [roten Pkw] und dem [Lkw] ein","Ich verzögere und fädele nach dem [gelben Fahrzeug] ein"],"oe":["I accelerate and merge in front of the [truck]","I slow down and merge between the [red car] and the [truck]","I slow down and merge after the [yellow vehicle]"],"ans":[0],"t":"single","num":null,"cd":"Sie haben auf dem Einfädelungsstreifen bereits den Lkw, der auf der rechten Fahrspur der Autobahn fährt, überholt. Wenn Sie nun weiter beschleunigen, können Sie vor dem Ende des Fahrstreifens auf die Hauptfahrbahn auffahren. Das sollten Sie tun.","ce":"They have already passed the truck on the acceleration lane on the right-hand side of the freeway. If you continue to accelerate, you can drive onto the main lane before the end of the lane. You should do that.","img":"2_2_18-017-M","vid":true,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.2.-behaviour-in-traffic/2.2.18-motorways-and-motorways/2.2.18-017-M"},{"id":"2.2.18-022","th":"2.2","thd":"Verhalten Im Strassenverkehr","the":"Behaviour In Traffic","ch":"2.2.18","chd":"Autobahnen Und Kraftfahrstrassen","che":"Motorways And Motorways","pt":4,"qd":"Sie möchten die Autobahn an der nächsten Ausfahrt verlassen. Wie verhalten Sie sich in dieser Situation richtig?","qe":"You want to leave the motorway at the next exit. What is the correct course of action in this situation?","od":["Ich beobachte den nachfolgenden Verkehr","Ich beginne jetzt, rechts zu blinken","Ich bremse ab jetzt gleichmäßig auf 60 km/h ab"],"oe":["I observe the traffic behind me","I turn on my right-side indicators now","I begin now to smoothly brake down to 60 km/h"],"ans":[0,1],"t":"multi","num":null,"cd":"Beim Verlassen der Autobahn solltest du spätestens 300 m vor der Ausfahrt den Blinker setzen.\nBeobachte bei Autobahnfahrten immer aufmerksam den nachfolgenden Verkehr. Achte besonders beim Befahren der Ausfahrt darauf, dass  niemand versucht dich rechts zu überholen.","ce":"When leaving the motorway, you should set the indicator at least 300 m before the exit.\nAlways keep a close eye on the traffic behind you when driving on the motorway. Especially when exiting the motorway, make sure that nobody tries to overtake you on the right.","img":"2_2_18-022","vid":true,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.2.-behaviour-in-traffic/2.2.18-motorways-and-motorways/2.2.18-022"},{"id":"2.7.01-045","th":"2.7","thd":"Technik","the":"Technology","ch":"2.7.01","chd":"Fahrbetrieb Fahrphysik Fahrtechnik","che":"Driving Operation Driving Physics Driving Technique","pt":3,"qd":"Was ist beim Kontrollieren des Reifenluftdrucks zu berücksichtigen?","qe":"What must you take into consideration when checking tyre pressure?","od":["Beladung/Besetzung des Fahrzeugs","Temperatur der Reifen","Werkstoff der Felgen (Stahl/Leichtmetall)"],"oe":["Load/Number of passengers in the car","Tyre temperature","Material of the wheels (steel/aluminium)"],"ans":[0,1],"t":"multi","num":null,"cd":"Wenn Sie den Reifenluftdruck überprüfen, müssen Sie auch die Temperatur und die Beladung des Fahrzeuges berücksichtigen. Diese können den Reifenluftdruck beeinflussen. Keine Rolle spielt dagegen der Werkstoff der Felge.","ce":"When checking tire pressure, you must also take into account the temperature and load of the vehicle. These can influence the tire pressure. By contrast, the material of the wheel rim doesn't matter.","img":null,"vid":false,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.7.-technology/2.7.01-driving-operation-driving-physics-driving-technique/2.7.01-045"},{"id":"2.2.05-019","th":"2.2","thd":"Verhalten Im Strassenverkehr","the":"Behaviour In Traffic","ch":"2.2.05","chd":"Ueberholen","che":"Overtaking","pt":5,"qd":"Warum dürfen Sie den vor Ihnen fahrenden Bus jetzt nicht überholen?","qe":"Why are you not permitted to now overtake the bus driving ahead of you?","od":["Wegen des eingeschalteten Warnblinklichts am Bus","Wegen des Motorrads","Wegen der fehlenden Fahrbahnmarkierungen"],"oe":["Because the hazard lights of the bus are switched on","Because of the motorbike","Because of the lack of road markings"],"ans":[0,1],"t":"multi","num":null,"cd":"Der Bus hat das Warnblinklicht eingeschaltet und befindet sich noch in der Anfahrt auf die Haltestelle. In diesem Fall ist es nicht gestattet den Bus zu Überholen. Zudem hat das Motorrad hinter dir zum Überholen angesetzt.","ce":"The bus has turned on the warning lights and is still driving to the bus stop. In this case, it is not allowed to overtake the bus. In addition, the motorbike behind you has started to overtake.","img":"2_2_05-019","vid":true,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.2.-behaviour-in-traffic/2.2.05-overtaking/2.2.05-019"},{"id":"2.5.01-207","th":"2.5","thd":"Umweltschutz","the":"Environmental Protection","ch":"2.5.01","chd":"Umweltschutz","che":"Environmental Protection","pt":3,"qd":"Wie können Sie bereits bei der Planung Ihrer Fahrten zum Umweltschutz beitragen?","qe":"When planning your journeys, how can you make them environmentally-friendlier?","od":["- mehrere Fahrziele in einer Fahrt zusammenlege","- Fahrgemeinschaften mit anderen Fahrzeugnutzern bilde","- plane, öffentliche Verkehrsmittel statt des eigenen Fahrzeugs zu nutzen"],"oe":["- combining several destinations into one single trip","- forming car pools with other vehicle users","- planning to use public transport instead of my own vehicle"],"ans":[0,1,2],"t":"multi","num":null,"cd":"Der Umwelt zuliebe sollten Kfz-FahrerInnen auf alle Fahrten verzichten, die nicht unbedingt notwendig sind. Planen Sie Ihre Fahrten deshalb gut und bilden Sie so oft wie möglich Fahrgemeinschaften, da hierdurch unnötige Fahrten vermieden werden. Ein positiver Beitrag zum aktiven Umweltschutz ist ferner die Nutzung von öffentlichen Verkehrsmitteln.","ce":"For the sake of the environment, motorists should refrain from all trips that are not absolutely necessary. Therefore, plan your trips well and make carpools as often as possible to avoid unnecessary trips. Another positive contribution to active environmental protection is the use of public transport.","img":null,"vid":false,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.5.-environmental-protection/2.5.01-environmental-protection/2.5.01-207"},{"id":"2.2.03-008","th":"2.2","thd":"Verhalten Im Strassenverkehr","the":"Behaviour In Traffic","ch":"2.2.03","chd":"Geschwindigkeit","che":"Speed","pt":2,"qd":"Sie fahren 100 km/h und haben 1 Sekunde Reaktionszeit. Wie lang ist der Reaktionsweg nach der Faustformel?","qe":"You are travelling at 100 km/h and have a reaction time of 1 second. What is the reaction distance according to the rule of thumb?","od":[],"oe":[],"ans":[],"t":"num","num":"30","cd":"Reaktionsweg = (Geschwindigkeit : 10) x 3\nDas heißt bei einer Geschwindigkeit von 100 km/h beträgt der Reaktionsweg 30 Meter.","ce":"Reaction path = (speed/10) x 3\nThat means at a speed of 100 km/h, the braking distance is 30 meters.","img":null,"vid":false,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.2.-behaviour-in-traffic/2.2.03-speed/2.2.03-008"},{"id":"2.2.03-012","th":"2.2","thd":"Verhalten Im Strassenverkehr","the":"Behaviour In Traffic","ch":"2.2.03","chd":"Geschwindigkeit","che":"Speed","pt":4,"qd":"Sie fahren auf einer sehr schmalen Straße und haben 50 m Sichtweite. Wie lang darf Ihr Anhalteweg höchstens sein?","qe":"You are driving on a very narrow road and can see 50 m ahead. What must be your maximum stopping distance?","od":[],"oe":[],"ans":[],"t":"num","num":"25","cd":"Bei einer schmalen Straßenführung muss man innerhalb der halben Sichtweite anhalten, da auch der Gegenverkehr rechtzeitig anhalten muss.","ce":"On a narrow street you have to stop within half the visibility, in this case 25m.","img":null,"vid":false,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.2.-behaviour-in-traffic/2.2.03-speed/2.2.03-012"},{"id":"2.1.06-031-M","th":"2.1","thd":"Gefahrenlehre","the":"Danger Teaching","ch":"2.1.06","chd":"Ueberholen","che":"Overtaking","pt":4,"qd":"Warum müssen Sie den Überholvorgang jetzt abbrechen?","qe":"Why must you discontinue your overtaking manoeuvre here?","od":["Weil der Traktor nach links abbiegen wird","Weil das Motorrad mich überholen wird","Weil ein Überholverbotsschild in Sicht ist"],"oe":["Because the tractor will turn off to the left","Because the motorbike will overtake me","Because I can see a no-overtaking sign"],"ans":[0],"t":"single","num":null,"cd":"Der Traktor setzt zum Linksabbiegen an. Dabei fährt der Traktor über die linke Spur der Fahrbahn. Wenn Du jetzt überholst, würdest Du mit dem Traktor kollidieren.","ce":"The tractor starts to turn left. The tractor drives across the left lane of the road. If you overtake now, you would collide with the tractor.","img":"2_1_06-031-M","vid":true,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.1.-danger-teaching/2.1.06-overtaking/2.1.06-031-M"},{"id":"2.2.05-013","th":"2.2","thd":"Verhalten Im Strassenverkehr","the":"Behaviour In Traffic","ch":"2.2.05","chd":"Ueberholen","che":"Overtaking","pt":5,"qd":"Auf wen müssen Sie in dieser Situation besonders achten?","qe":"To whom must you pay particularly close attention in this situation?","od":["- Radfahrer","- roten Pkw","- weißen Lkw"],"oe":["- cyclist","- red car","- white truck"],"ans":[0],"t":"single","num":null,"cd":"In dieser Situation müssen Sie als Kfz-FahrerIn auf den Radfahrer achten, der sich Ihnen von rechts nähert. Der Radfahrer könnte vor dem Lkw auf die Straße fahren und dadurch eine gefährliche Situation herbeiführen.","ce":"In this situation, as a car driver you have to pay attention to the cyclist who approaches you from the right. The cyclist could drive onto the road in front of the truck, causing a dangerous situation.","img":"2_2_05-013","vid":true,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.2.-behaviour-in-traffic/2.2.05-overtaking/2.2.05-013"},{"id":"2.2.13-002","th":"2.2","thd":"Verhalten Im Strassenverkehr","the":"Behaviour In Traffic","ch":"2.2.13","chd":"Einrichtungen Zur Ueberwachung Der Parkzeit","che":"Parking Time Monitoring Devices","pt":2,"qd":"Eine Parkuhr ist noch nicht abgelaufen. Wie verhalten Sie sich?","qe":"The time on a parking meter has not yet run out. What do you do?","od":["- ausnutzen, ohne die Parkuhr erneut zu betätigen","- nicht ausnutzen","- nur ausnutzen, wenn Sie eine Parkscheibe verwenden"],"oe":["- use the time left on the meter without inserting more money","- not use the time left on the meter","- only use the time left on the meter when using a parking disc"],"ans":[0],"t":"single","num":null,"cd":"Wenn eine Parkuhr noch nicht abgelaufen ist, dürfen Sie die restliche Parkzeit nutzen und Ihr Fahrzeug für die verbleibende Zeit kostenfrei auf dem dortigen Parkplatz abstellen. Dazu benötigen Sie keine Parkscheibe.","ce":"If a parking meter has not yet expired, you may use the rest of the parking time and leave your vehicle for free at the parking lot for the remaining time. You do not need a parking disc for this.","img":null,"vid":false,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.2.-behaviour-in-traffic/2.2.13-parking-time-monitoring-devices/2.2.13-002"},{"id":"2.2.05-014-M","th":"2.2","thd":"Verhalten Im Strassenverkehr","the":"Behaviour In Traffic","ch":"2.2.05","chd":"Ueberholen","che":"Overtaking","pt":4,"qd":"Warum müssen Sie jetzt verzögern?","qe":"Why do you have to slow down here?","od":["- Motorrads","- Traktors","- Geländewagens"],"oe":["- motorbike","- tractor","- SUV"],"ans":[0],"t":"single","num":null,"cd":"Der/die überholende MotorradfahrerIn stellt für Sie eine Gefahr dar. Er kommt Ihnen während seines Überholvorgangs in Ihrem Fahrstreifen entgegen. Sie sollten verzögern und so einen Zusammenstoß vermeiden. Das Verhalten der anderen Kfz-FahrerInnen ist verkehrskonform.","ce":"The overtaking motorcyclist represents a danger to you. He will meet you in your lane during his overtaking process. You should delay and avoid a collision. The behavior of the other drivers is traffic compliant.","img":"2_2_05-014-M","vid":true,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.2.-behaviour-in-traffic/2.2.05-overtaking/2.2.05-014-M"},{"id":"2.2.03-007","th":"2.2","thd":"Verhalten Im Strassenverkehr","the":"Behaviour In Traffic","ch":"2.2.03","chd":"Geschwindigkeit","che":"Speed","pt":2,"qd":"Sie fahren 100 km/h und führen eine normale Bremsung durch. Wie lang ist der Bremsweg nach der Faustformel?","qe":"You are travelling at 100 km/h and brake normally. What is the braking distance according to the rule of thumb?","od":[],"oe":[],"ans":[],"t":"num","num":"100","cd":"Bremsweg = (Geschwindigkeit : 10) x (Geschwindigkeit : 10)\nDas heißt bei einer Geschwindigkeit von 100 km/h beträgt der Bremsweg 100 Meter.","ce":"Braking distance = (speed/10) x (speed/10)\nThat means at a speed of 100 km/h, the braking distance is 100 meters.","img":null,"vid":false,"u":"https://www.clickclickdrive.de/fragenkatalog/en/2.2.-behaviour-in-traffic/2.2.03-speed/2.2.03-007"}];
